@dataclass(frozen=True)
class PcbDocBoardDataEntry(PcbKeyValueTextEntryMixin):
    raw: str


class _PcbDocEntryLookupMixin:
    entries: tuple[PcbDocBoardDataEntry, ...]

    def get_value(
        self, key: str, default: str | None = None, occurrence: int = 0
    ) -> str | None:
        seen = 0
        for entry in self.entries:
            if entry.key != key:
                continue
            if seen == occurrence:
                return entry.value
            seen += 1
        return default


def _coerce_mechanical_layer_id(layer: int | str | PcbLayer) -> int:
    if isinstance(layer, PcbLayer):
        layer_id = int(layer)
    elif isinstance(layer, int):
        layer_id = int(layer)
    else:
        token = "".join(ch for ch in str(layer or "").upper() if ch.isalnum())
        if token.isdigit():
            layer_id = int(token)
        else:
            try:
                layer_id = int(PcbLayer.from_json_name(token))
            except ValueError as exc:
                raise ValueError(f"Unsupported mechanical layer: {layer!r}") from exc
    if not PcbLayer.MECHANICAL_1.value <= layer_id <= PcbLayer.MECHANICAL_16.value:
        raise ValueError(f"Layer is not Mechanical 1..16: {layer!r}")
    return layer_id


def _mechanical_layer_number(layer_id: int) -> int:
    return int(layer_id) - PcbLayer.MECHANICAL_1.value + 1


@dataclass(frozen=True)
class PcbDocBoardDataSegment(_PcbDocEntryLookupMixin):
    entries: tuple[PcbDocBoardDataEntry, ...]
    leading_pipe: bool = True

    @classmethod
    def from_text(cls, text: str) -> "PcbDocBoardDataSegment":
        leading_pipe = text.startswith("|")
        if leading_pipe:
            text = text[1:]
        if not text:
            return cls(entries=tuple(), leading_pipe=leading_pipe)
        return cls(
            entries=tuple(PcbDocBoardDataEntry(raw=part) for part in text.split("|")),
            leading_pipe=leading_pipe,
        )

    def serialize(self) -> str:
        text = "|".join(entry.raw for entry in self.entries)
        if self.leading_pipe:
            text = "|" + text
        return text

    def to_mapping(self) -> dict[str, str]:
        result: dict[str, str] = {}
        for entry in self.entries:
            if entry.key is None or entry.value is None:
                continue
            result[entry.key] = entry.value
        return result

    def with_updated_value(
        self, key: str, value: str, occurrence: int = 0
    ) -> "PcbDocBoardDataSegment":
        seen = 0
        updated = False
        new_entries: list[PcbDocBoardDataEntry] = []
        for entry in self.entries:
            if entry.key == key and seen == occurrence:
                new_entries.append(PcbDocBoardDataEntry(raw=f"{key}={value}"))
                updated = True
            else:
                new_entries.append(entry)
            if entry.key == key:
                seen += 1
        if not updated:
            raise KeyError(f"Board data key not found: {key}")
        return PcbDocBoardDataSegment(
            entries=tuple(new_entries), leading_pipe=self.leading_pipe
        )

    def with_replaced_entries(
        self,
        predicate: Callable[[PcbDocBoardDataEntry], bool],
        replacement_entries: Sequence[PcbDocBoardDataEntry],
    ) -> "PcbDocBoardDataSegment":
        new_entries: list[PcbDocBoardDataEntry] = []
        replaced = False
        inserted = False
        for entry in self.entries:
            if predicate(entry):
                if not inserted:
                    new_entries.extend(replacement_entries)
                    inserted = True
                replaced = True
                continue
            new_entries.append(entry)
        if not replaced:
            raise KeyError("Board data entry range to replace was not found")
        return PcbDocBoardDataSegment(
            entries=tuple(new_entries), leading_pipe=self.leading_pipe
        )


@dataclass(frozen=True)
class PcbDocNestedConfig(_PcbDocEntryLookupMixin):
    entries: tuple[PcbDocBoardDataEntry, ...]
    leading_backtick: bool = True

    @classmethod
    def from_value(cls, value: str) -> "PcbDocNestedConfig":
        leading_backtick = value.startswith("`")
        if leading_backtick:
            value = value[1:]
        if not value:
            return cls(entries=tuple(), leading_backtick=leading_backtick)
        return cls(
            entries=tuple(PcbDocBoardDataEntry(raw=part) for part in value.split("`")),
            leading_backtick=leading_backtick,
        )

    def serialize(self) -> str:
        text = "`".join(entry.raw for entry in self.entries)
        if self.leading_backtick:
            text = "`" + text
        return text

    def with_updated_value(
        self, key: str, value: str, occurrence: int = 0
    ) -> "PcbDocNestedConfig":
        seen = 0
        updated = False
        new_entries: list[PcbDocBoardDataEntry] = []
        for entry in self.entries:
            if entry.key == key and seen == occurrence:
                new_entries.append(PcbDocBoardDataEntry(raw=f"{key}={value}"))
                updated = True
            else:
                new_entries.append(entry)
            if entry.key == key:
                seen += 1
        if not updated:
            raise KeyError(f"Nested board config key not found: {key}")
        return PcbDocNestedConfig(
            entries=tuple(new_entries), leading_backtick=self.leading_backtick
        )


@dataclass(frozen=True)
class PcbDocBoardData:
    """
    Ordered representation of the monolithic `Board6/Data` board text stream.

    The stream is a single length-prefixed text record containing multiple
    carriage-return-separated `|RECORD=Board|...` segments plus a top-level
    metadata segment. We preserve segment/entry ordering exactly so the empty
    board can be re-synthesized byte-for-byte while still exposing the first
    useful semantic fields through a structured API.
    """

    segments: tuple[PcbDocBoardDataSegment, ...]
    trailing_nul: bool = True

    @classmethod
    def default(cls) -> "PcbDocBoardData":
        return cls(
            segments=tuple(
                PcbDocBoardDataSegment.from_text(text)
                for text in DEFAULT_PCBDOC_BOARD_SEGMENT_TEXTS
            ),
            trailing_nul=DEFAULT_PCBDOC_BOARD_TRAILING_NUL,
        )

    @classmethod
    def from_bytes(cls, data: bytes) -> "PcbDocBoardData":
        if len(data) < 4:
            raise ValueError("Invalid Board6/Data stream")
        length = struct.unpack("<I", data[:4])[0]
        if len(data) < 4 + length:
            raise ValueError("Invalid Board6/Data stream")
        body_bytes = data[4 : 4 + length]
        trailing_nul = body_bytes.endswith(b"\x00")
        if trailing_nul:
            body_bytes = body_bytes[:-1]
        text = body_bytes.decode("cp1252", errors="replace")
        return cls(
            segments=tuple(
                PcbDocBoardDataSegment.from_text(part) for part in text.split("\r")
            ),
            trailing_nul=trailing_nul,
        )

    def build_stream(self) -> bytes:
        body = "\r".join(segment.serialize() for segment in self.segments)
        if self.trailing_nul:
            body += "\x00"
        return _build_length_prefixed_ascii(body)

    def build_header(self) -> bytes:
        return struct.pack("<I", 1)

    @property
    def segment_count(self) -> int:
        return len(self.segments)

    @property
    def top_level_segment(self) -> PcbDocBoardDataSegment:
        return self.segments[0]

    @property
    def record_segments(self) -> tuple[PcbDocBoardDataSegment, ...]:
        return self.segments[1:]

    @property
    def metadata(self) -> PcbDocBoardMetadata:
        return PcbDocBoardMetadata(
            filename=self.top_level_segment.get_value("FILENAME"),
            kind=self.top_level_segment.get_value("KIND"),
            version=self.top_level_segment.get_value("VERSION"),
            date=self.top_level_segment.get_value("DATE"),
            time=self.top_level_segment.get_value("TIME"),
        )

    @property
    def filename(self) -> str | None:
        return self.metadata.filename

    @property
    def kind(self) -> str | None:
        return self.metadata.kind

    @property
    def version(self) -> str | None:
        return self.metadata.version

    @property
    def date(self) -> str | None:
        return self.metadata.date

    @property
    def time(self) -> str | None:
        return self.metadata.time

    @property
    def origin(self) -> PcbDocBoardOrigin | None:
        x_mils = _parse_mil_text(self.top_level_segment.get_value("ORIGINX"))
        y_mils = _parse_mil_text(self.top_level_segment.get_value("ORIGINY"))
        if x_mils is None or y_mils is None:
            return None
        return PcbDocBoardOrigin(x_mils=x_mils, y_mils=y_mils)

    @property
    def sheet_frame(self) -> PcbDocBoardSheetFrame | None:
        x_mils = _parse_mil_text(self.top_level_segment.get_value("SHEETX"))
        y_mils = _parse_mil_text(self.top_level_segment.get_value("SHEETY"))
        width_mils = _parse_mil_text(self.top_level_segment.get_value("SHEETWIDTH"))
        height_mils = _parse_mil_text(self.top_level_segment.get_value("SHEETHEIGHT"))
        if (
            x_mils is None
            or y_mils is None
            or width_mils is None
            or height_mils is None
        ):
            return None
        return PcbDocBoardSheetFrame(
            x_mils=x_mils,
            y_mils=y_mils,
            width_mils=width_mils,
            height_mils=height_mils,
        )

    @property
    def view_state(self) -> PcbDocViewState | None:
        current_view_state = self.current_view_state
        if current_view_state is None:
            return None
        return PcbDocViewState(current_view_state)

    @property
    def current_view_state(self) -> str | None:
        for segment in self.record_segments:
            value = segment.get_value("CURRENT2D3DVIEWSTATE")
            if value is not None:
                return value
        return None

    @property
    def viewport(self) -> PcbDocViewport | None:
        bounds = self.viewport_bounds
        if bounds is None:
            return None
        return PcbDocViewport(
            low_x=bounds[0],
            high_x=bounds[1],
            low_y=bounds[2],
            high_y=bounds[3],
        )

    @property
    def viewport_bounds(self) -> tuple[int, int, int, int] | None:
        for segment in self.record_segments:
            lx = segment.get_value("VP.LX")
            hx = segment.get_value("VP.HX")
            ly = segment.get_value("VP.LY")
            hy = segment.get_value("VP.HY")
            if lx is None or hx is None or ly is None or hy is None:
                continue
            return int(lx), int(hx), int(ly), int(hy)
        return None

    @property
    def config_2d_full_filename(self) -> str | None:
        for segment in self.record_segments:
            value = segment.get_value("2DCONFIGFULLFILENAME")
            if value is not None:
                return value
        return None

    @property
    def config_2d(self) -> PcbDoc2DConfiguration:
        nested_config = self.get_nested_config("2DCONFIGURATION")
        return PcbDoc2DConfiguration(
            full_filename=self.config_2d_full_filename,
            nested_config=nested_config,
            settings=PcbDoc2DViewSettings(
                current_layer=(
                    nested_config.get_value("CFG2D.CURRENTLAYER")
                    if nested_config is not None
                    else None
                )
            ),
        )

    @property
    def config_3d_full_filename(self) -> str | None:
        for segment in self.record_segments:
            value = segment.get_value("3DCONFIGFULLFILENAME")
            if value is not None:
                return value
        return None

    @property
    def config_3d(self) -> PcbDoc3DConfiguration:
        nested_config = self.get_nested_config("3DCONFIGURATION")
        return PcbDoc3DConfiguration(
            full_filename=self.config_3d_full_filename,
            nested_config=nested_config,
            settings=PcbDoc3DViewSettings(
                top_solder_mask_color=_parse_int_text(
                    nested_config.get_value("CFG3D.TOPSOLDERMASKCOLOR")
                    if nested_config is not None
                    else None
                ),
                bottom_solder_mask_color=_parse_int_text(
                    nested_config.get_value("CFG3D.BOTSOLDERMASKCOLOR")
                    if nested_config is not None
                    else None
                ),
            ),
        )

    @property
    def top_level_board(self) -> AltiumBoard:
        return AltiumBoard.from_record(self.top_level_segment.to_mapping())

    def with_segment(
        self, index: int, segment: PcbDocBoardDataSegment
    ) -> "PcbDocBoardData":
        new_segments = list(self.segments)
        new_segments[index] = segment
        return PcbDocBoardData(
            segments=tuple(new_segments), trailing_nul=self.trailing_nul
        )

    def with_top_level_value(
        self, key: str, value: str, occurrence: int = 0
    ) -> "PcbDocBoardData":
        return self.with_segment(
            0,
            self.top_level_segment.with_updated_value(
                key, value, occurrence=occurrence
            ),
        )

    def with_metadata(self, metadata: PcbDocBoardMetadata) -> "PcbDocBoardData":
        updated = self.with_top_level_value("FILENAME", metadata.filename or "")
        updated = updated.with_top_level_value("KIND", metadata.kind or "")
        updated = updated.with_top_level_value("VERSION", metadata.version or "")
        updated = updated.with_top_level_value("DATE", metadata.date or "")
        updated = updated.with_top_level_value("TIME", metadata.time or "")
        return updated

    def with_origin(self, origin: PcbDocBoardOrigin) -> "PcbDocBoardData":
        return self.with_origin_mils(origin.x_mils, origin.y_mils)

    def with_origin_mils(self, x_mils: float, y_mils: float) -> "PcbDocBoardData":
        updated = self.top_level_segment.with_updated_value(
            "ORIGINX", _format_mil_value(x_mils)
        )
        updated = updated.with_updated_value("ORIGINY", _format_mil_value(y_mils))
        return self.with_segment(0, updated)

    def with_sheet_frame(self, sheet_frame: PcbDocBoardSheetFrame) -> "PcbDocBoardData":
        return self.with_sheet_frame_mils(
            sheet_frame.x_mils,
            sheet_frame.y_mils,
            sheet_frame.width_mils,
            sheet_frame.height_mils,
        )

    def with_sheet_frame_mils(
        self,
        x_mils: float,
        y_mils: float,
        width_mils: float,
        height_mils: float,
    ) -> "PcbDocBoardData":
        updated = self.top_level_segment.with_updated_value(
            "SHEETX", _format_mil_value(x_mils)
        )
        updated = updated.with_updated_value("SHEETY", _format_mil_value(y_mils))
        updated = updated.with_updated_value(
            "SHEETWIDTH", _format_mil_value(width_mils)
        )
        updated = updated.with_updated_value(
            "SHEETHEIGHT", _format_mil_value(height_mils)
        )
        return self.with_segment(0, updated)

    def with_current_view_state(self, value: str) -> "PcbDocBoardData":
        for index, segment in enumerate(self.record_segments, start=1):
            if segment.get_value("CURRENT2D3DVIEWSTATE") is None:
                continue
            return self.with_segment(
                index, segment.with_updated_value("CURRENT2D3DVIEWSTATE", value)
            )
        raise KeyError("CURRENT2D3DVIEWSTATE segment not found")

    def with_view_state(self, value: str | PcbDocViewState) -> "PcbDocBoardData":
        return self.with_current_view_state(str(value))

    def with_viewport_bounds(
        self,
        lx: int,
        hx: int,
        ly: int,
        hy: int,
    ) -> "PcbDocBoardData":
        for index, segment in enumerate(self.record_segments, start=1):
            if None in (
                segment.get_value("VP.LX"),
                segment.get_value("VP.HX"),
                segment.get_value("VP.LY"),
                segment.get_value("VP.HY"),
            ):
                continue
            updated = segment.with_updated_value("VP.LX", str(int(lx)))
            updated = updated.with_updated_value("VP.HX", str(int(hx)))
            updated = updated.with_updated_value("VP.LY", str(int(ly)))
            updated = updated.with_updated_value("VP.HY", str(int(hy)))
            return self.with_segment(index, updated)
        raise KeyError("Viewport segment not found")

    def with_viewport(self, viewport: PcbDocViewport) -> "PcbDocBoardData":
        return self.with_viewport_bounds(
            viewport.low_x,
            viewport.high_x,
            viewport.low_y,
            viewport.high_y,
        )

    def with_config_2d_full_filename(self, value: str) -> "PcbDocBoardData":
        return self.with_record_value("2DCONFIGFULLFILENAME", value)

    def with_config_3d_full_filename(self, value: str) -> "PcbDocBoardData":
        return self.with_record_value("3DCONFIGFULLFILENAME", value)

    def with_2d_current_layer(self, layer_token: str) -> "PcbDocBoardData":
        return self.with_nested_config_value(
            "2DCONFIGURATION", "CFG2D.CURRENTLAYER", layer_token
        )

    def with_config_2d(self, config: PcbDoc2DConfiguration) -> "PcbDocBoardData":
        updated = self
        if config.full_filename is not None:
            updated = updated.with_config_2d_full_filename(config.full_filename)
        if config.settings.current_layer is not None:
            updated = updated.with_2d_current_layer(config.settings.current_layer)
        return updated

    def with_3d_solder_mask_colors(
        self,
        *,
        top_color: int | None = None,
        bottom_color: int | None = None,
    ) -> "PcbDocBoardData":
        updated = self
        if top_color is not None:
            updated = updated.with_nested_config_value(
                "3DCONFIGURATION",
                "CFG3D.TOPSOLDERMASKCOLOR",
                str(int(top_color)),
            )
        if bottom_color is not None:
            updated = updated.with_nested_config_value(
                "3DCONFIGURATION",
                "CFG3D.BOTSOLDERMASKCOLOR",
                str(int(bottom_color)),
            )
        return updated

    def with_config_3d(self, config: PcbDoc3DConfiguration) -> "PcbDocBoardData":
        updated = self
        if config.full_filename is not None:
            updated = updated.with_config_3d_full_filename(config.full_filename)
        updated = updated.with_3d_solder_mask_colors(
            top_color=config.settings.top_solder_mask_color,
            bottom_color=config.settings.bottom_solder_mask_color,
        )
        return updated

    def get_record_segment(self, key: str) -> PcbDocBoardDataSegment | None:
        for segment in self.record_segments:
            if segment.get_value(key) is not None:
                return segment
        return None

    def get_nested_config(self, key: str) -> PcbDocNestedConfig | None:
        segment = self.get_record_segment(key)
        if segment is None:
            return None
        value = segment.get_value(key)
        if value is None:
            return None
        return PcbDocNestedConfig.from_value(value)

    def with_record_value(self, key: str, value: str) -> "PcbDocBoardData":
        for index, segment in enumerate(self.record_segments, start=1):
            if segment.get_value(key) is None:
                continue
            return self.with_segment(index, segment.with_updated_value(key, value))
        raise KeyError(f"Board data record key not found: {key}")

    def with_nested_config_value(
        self,
        config_key: str,
        nested_key: str,
        nested_value: str,
        occurrence: int = 0,
    ) -> "PcbDocBoardData":
        for index, segment in enumerate(self.record_segments, start=1):
            config_value = segment.get_value(config_key)
            if config_value is None:
                continue
            nested = PcbDocNestedConfig.from_value(config_value)
            updated = nested.with_updated_value(
                nested_key, nested_value, occurrence=occurrence
            )
            return self.with_segment(
                index,
                segment.with_updated_value(config_key, updated.serialize()),
            )
        raise KeyError(f"Nested config segment not found: {config_key}")

    def with_outline(self, outline: AltiumBoardOutline) -> "PcbDocBoardData":
        """
        Replace the board outline with line/arc-capable outline geometry.
        """
        if outline.vertex_count < 3:
            raise ValueError("Board outline requires at least 3 vertices")

        outline_vertices = list(outline.vertices)
        first = outline_vertices[0]
        last = outline_vertices[-1]
        if (first.x_mils, first.y_mils) != (last.x_mils, last.y_mils):
            outline_vertices.append(BoardOutlineVertex.line(first.x_mils, first.y_mils))

        replacement_entries: list[PcbDocBoardDataEntry] = []
        for index, vertex in enumerate(outline_vertices):
            replacement_entries.extend(
                (
                    PcbDocBoardDataEntry(
                        raw=f"KIND{index}={1 if vertex.is_arc else 0}"
                    ),
                    PcbDocBoardDataEntry(
                        raw=f"VX{index}={_format_mil_value(vertex.x_mils)}"
                    ),
                    PcbDocBoardDataEntry(
                        raw=f"VY{index}={_format_mil_value(vertex.y_mils)}"
                    ),
                    PcbDocBoardDataEntry(
                        raw=f"CX{index}={_format_mil_value(vertex.center_x_mils)}"
                    ),
                    PcbDocBoardDataEntry(
                        raw=f"CY{index}={_format_mil_value(vertex.center_y_mils)}"
                    ),
                    PcbDocBoardDataEntry(
                        raw=f"SA{index}={_format_outline_angle_value(vertex.start_angle_deg)}"
                    ),
                    PcbDocBoardDataEntry(
                        raw=f"EA{index}={_format_outline_angle_value(vertex.end_angle_deg)}"
                    ),
                    PcbDocBoardDataEntry(
                        raw=f"R{index}={_format_mil_value(vertex.radius_mils)}"
                    ),
                )
            )

        return self.with_segment(
            0,
            self.top_level_segment.with_replaced_entries(
                lambda entry: _is_outline_entry_key(entry.key),
                replacement_entries,
            ),
        )

    def with_outline_vertices(
        self, vertices_mils: Sequence[tuple[float, float]]
    ) -> "PcbDocBoardData":
        return self.with_outline(_outline_from_points(vertices_mils))

    def default_substack_guid(self) -> str:
        for segment in self.segments:
            value = segment.get_value("LAYERPAIR0SUBSTACK_0")
            if value:
                return value
        for segment in self.segments:
            for entry in segment.entries:
                key = entry.key or ""
                if key.startswith("V9_STACK_LAYER") and key.endswith("CONTEXT"):
                    suffix = key.rsplit("_", 1)[-1]
                    if suffix.endswith("CONTEXT"):
                        return "{" + suffix[:-7] + "}"
        raise KeyError("No default layer-stack substack GUID found in Board6/Data")

    def with_layer_stack_template(
        self,
        template: PcbDocLayerStackTemplate,
    ) -> "PcbDocBoardData":
        from .altium_layer_stack_document import AltiumLayerStackDocument

        document = AltiumLayerStackDocument.from_pcbdoc_layer_stack_template(
            template,
            base_board_data=self,
        )
        return document.to_board_data_for_new_pcbdoc(base_board_data=self)

    def _with_layer_stack_template_source(
        self,
        template: PcbDocLayerStackTemplate,
    ) -> "PcbDocBoardData":
        substack_guid = self.default_substack_guid()
        stack_replacement_entries = tuple(
            PcbDocBoardDataEntry(raw=raw)
            for raw in (
                list(PcbDocLayerStackBuilder.build_legacy_layer_entry_strings(template))
                + list(
                    PcbDocLayerStackBuilder.build_v9_stack_entry_strings(
                        template,
                        substack_guid=substack_guid,
                    )
                )
            )
        )
        stack_segment_index = self._segment_index_for_key("LAYER1NAME")
        if stack_segment_index is None:
            raise KeyError("Board6/Data layer stack segment not found")
        updated = self.with_segment(
            stack_segment_index,
            self.segments[stack_segment_index].with_replaced_entries(
                lambda entry: is_layer_stack_core_entry_key(entry.key),
                stack_replacement_entries,
            ),
        )
        layer_pair_segment_index = updated._segment_index_for_key("LAYERPAIR0LOW")
        if layer_pair_segment_index is None:
            raise KeyError("Board6/Data layer pair segment not found")
        updated = updated.with_segment(
            layer_pair_segment_index,
            updated.segments[layer_pair_segment_index].with_replaced_entries(
                lambda entry: is_layer_pair_entry_key(entry.key),
                tuple(
                    PcbDocBoardDataEntry(raw=raw)
                    for raw in PcbDocLayerStackBuilder.build_layer_pair_entry_strings(
                        template,
                        substack_guid=substack_guid,
                    )
                ),
            ),
        )
        return updated._with_v9_cache_names(
            {
                16777217: "Top Layer",
                16842751: "Bottom Layer",
                **{layer.v7_layer_id: layer.name for layer in template.copper_layers},
                **{
                    17039361 + index: dielectric.name
                    for index, dielectric in enumerate(template.dielectrics_between)
                },
            }
        )

    def _with_v9_cache_names(
        self, layer_names_by_id: dict[int, str]
    ) -> "PcbDocBoardData":
        cache_segment_index = self._segment_index_for_entry_predicate(
            lambda entry: bool(entry.key and LAYER_STACK_CACHE_RE.match(entry.key))
        )
        if cache_segment_index is None:
            raise KeyError("Board6/Data V9 cache segment not found")
        cache_segment = self.segments[cache_segment_index]
        entries = list(cache_segment.entries)
        groups: dict[int, dict[str, int]] = {}
        max_index = -1
        for index, entry in enumerate(entries):
            key = entry.key or ""
            match = LAYER_STACK_CACHE_RE.match(key)
            if not match:
                continue
            cache_index = int(match.group(1))
            suffix = match.group(2).upper()
            max_index = max(max_index, cache_index)
            groups.setdefault(cache_index, {})[suffix] = index

        updated_entries = list(entries)
        missing_pairs: list[PcbDocBoardDataEntry] = []
        for layer_id, layer_name in layer_names_by_id.items():
            found_group_index = None
            for cache_index, positions in groups.items():
                layerid_pos = positions.get("LAYERID")
                if layerid_pos is None:
                    continue
                if updated_entries[layerid_pos].value == str(int(layer_id)):
                    found_group_index = cache_index
                    name_pos = positions.get("NAME")
                    if name_pos is not None:
                        updated_entries[name_pos] = PcbDocBoardDataEntry(
                            raw=f"V9_CACHE_LAYER{cache_index}_NAME={layer_name}"
                        )
                    else:
                        insert_at = layerid_pos + 1
                        updated_entries.insert(
                            insert_at,
                            PcbDocBoardDataEntry(
                                raw=f"V9_CACHE_LAYER{cache_index}_NAME={layer_name}"
                            ),
                        )
                    break
            if found_group_index is not None:
                continue
            max_index += 1
            missing_pairs.extend(
                (
                    PcbDocBoardDataEntry(
                        raw=f"V9_CACHE_LAYER{max_index}_LAYERID={int(layer_id)}"
                    ),
                    PcbDocBoardDataEntry(
                        raw=f"V9_CACHE_LAYER{max_index}_NAME={layer_name}"
                    ),
                )
            )

        if missing_pairs:
            updated_entries.extend(missing_pairs)

        return self.with_segment(
            cache_segment_index,
            PcbDocBoardDataSegment(
                entries=tuple(updated_entries),
                leading_pipe=cache_segment.leading_pipe,
            ),
        )

    def _with_segment_value(
        self,
        key: str,
        value: str,
        *,
        preferred_segment_key: str | None = None,
    ) -> "PcbDocBoardData":
        segment_index = self._segment_index_for_key(key)
        if segment_index is not None:
            return self.with_segment(
                segment_index,
                self.segments[segment_index].with_updated_value(key, value),
            )

        if preferred_segment_key is not None:
            segment_index = self._segment_index_for_key(preferred_segment_key)
        if segment_index is None:
            segment_index = 0
        segment = self.segments[segment_index]
        return self.with_segment(
            segment_index,
            PcbDocBoardDataSegment(
                entries=(
                    *segment.entries,
                    PcbDocBoardDataEntry(raw=f"{key}={value}"),
                ),
                leading_pipe=segment.leading_pipe,
            ),
        )

    def _with_v9_cache_mechanical_layer(
        self,
        *,
        v7_layer_id: int,
        layer_name: str,
        enabled: bool,
    ) -> "PcbDocBoardData":
        cache_segment_index = self._segment_index_for_entry_predicate(
            lambda entry: bool(entry.key and LAYER_STACK_CACHE_RE.match(entry.key))
        )
        if cache_segment_index is None:
            raise KeyError("Board6/Data V9 cache segment not found")

        cache_segment = self.segments[cache_segment_index]
        entries = list(cache_segment.entries)
        groups: dict[int, dict[str, int]] = {}
        max_index = -1
        for index, entry in enumerate(entries):
            key = entry.key or ""
            match = LAYER_STACK_CACHE_RE.match(key)
            if not match:
                continue
            cache_index = int(match.group(1))
            suffix = match.group(2).upper()
            max_index = max(max_index, cache_index)
            groups.setdefault(cache_index, {})[suffix] = index

        enabled_text = _format_bool_text(enabled)
        found_group_index: int | None = None
        for cache_index, positions in groups.items():
            layerid_pos = positions.get("LAYERID")
            if layerid_pos is None:
                continue
            if entries[layerid_pos].value != str(int(v7_layer_id)):
                continue
            found_group_index = cache_index
            name_pos = positions.get("NAME")
            if name_pos is not None:
                entries[name_pos] = PcbDocBoardDataEntry(
                    raw=f"V9_CACHE_LAYER{cache_index}_NAME={layer_name}"
                )
            else:
                entries.append(
                    PcbDocBoardDataEntry(
                        raw=f"V9_CACHE_LAYER{cache_index}_NAME={layer_name}"
                    )
                )
            enabled_pos = positions.get("MECHENABLED")
            if enabled_pos is not None:
                entries[enabled_pos] = PcbDocBoardDataEntry(
                    raw=f"V9_CACHE_LAYER{cache_index}_MECHENABLED={enabled_text}"
                )
            else:
                entries.append(
                    PcbDocBoardDataEntry(
                        raw=f"V9_CACHE_LAYER{cache_index}_MECHENABLED={enabled_text}"
                    )
                )
            break

        if found_group_index is None:
            max_index += 1
            entries.extend(
                (
                    PcbDocBoardDataEntry(
                        raw=f"V9_CACHE_LAYER{max_index}_LAYERID={int(v7_layer_id)}"
                    ),
                    PcbDocBoardDataEntry(
                        raw=f"V9_CACHE_LAYER{max_index}_NAME={layer_name}"
                    ),
                    PcbDocBoardDataEntry(
                        raw=f"V9_CACHE_LAYER{max_index}_MECHENABLED={enabled_text}"
                    ),
                )
            )

        return self.with_segment(
            cache_segment_index,
            PcbDocBoardDataSegment(
                entries=tuple(entries),
                leading_pipe=cache_segment.leading_pipe,
            ),
        )

    def with_mechanical_layer(
        self,
        layer: int | str | PcbLayer,
        *,
        name: str | None = None,
        enabled: bool = True,
    ) -> "PcbDocBoardData":
        layer_id = _coerce_mechanical_layer_id(layer)
        mechanical_number = _mechanical_layer_number(layer_id)
        v7_layer_id = pcb_mechanical_layer_number_to_v7_saved_layer_id(
            mechanical_number
        )
        if v7_layer_id is None:
            raise ValueError(f"Unsupported mechanical layer: {layer!r}")

        legacy_name_key = f"LAYER{layer_id}NAME"
        existing_name = None
        if name is None:
            for segment in self.segments:
                found = segment.get_value(legacy_name_key)
                if found is not None and found.strip():
                    existing_name = found.strip()
                    break
            if existing_name is None:
                for segment in self.segments:
                    for entry in segment.entries:
                        key = entry.key or ""
                        match = LAYER_STACK_CACHE_RE.match(key)
                        if not match or match.group(2).upper() != "LAYERID":
                            continue
                        if entry.value != str(int(v7_layer_id)):
                            continue
                        name_key = f"V9_CACHE_LAYER{match.group(1)}_NAME"
                        for candidate in segment.entries:
                            if candidate.key == name_key and candidate.value:
                                existing_name = candidate.value.strip()
                                break
                        break
                    if existing_name is not None:
                        break
        layer_name = (
            (name or "").strip() or existing_name or f"Mechanical {mechanical_number}"
        )

        prefix = f"LAYER{layer_id}"
        updated = self._with_segment_value(
            legacy_name_key,
            layer_name,
            preferred_segment_key="LAYER1NAME",
        )
        updated = updated._with_segment_value(
            f"{prefix}MECHENABLED",
            _format_bool_text(enabled),
            preferred_segment_key="LAYER1NAME",
        )
        return updated._with_v9_cache_mechanical_layer(
            v7_layer_id=v7_layer_id,
            layer_name=layer_name,
            enabled=enabled,
        )

    def _next_mechanical_pair_index(self) -> int:
        pair_indices: set[int] = set()
        for segment in self.segments:
            for entry in segment.entries:
                key = entry.key or ""
                match = re.fullmatch(r"MECHPAIR(\d+)L[12]", key, re.IGNORECASE)
                if match:
                    pair_indices.add(int(match.group(1)))
        candidate = 0
        while candidate in pair_indices:
            candidate += 1
        return candidate

    def with_mechanical_layer_pair(
        self,
        layer_1: int | str | PcbLayer,
        layer_2: int | str | PcbLayer,
        *,
        pair_index: int | None = None,
    ) -> "PcbDocBoardData":
        layer_1_id = _coerce_mechanical_layer_id(layer_1)
        layer_2_id = _coerce_mechanical_layer_id(layer_2)
        if layer_1_id == layer_2_id:
            raise ValueError("Mechanical layer pair endpoints must differ")
        resolved_pair_index = (
            self._next_mechanical_pair_index()
            if pair_index is None
            else int(pair_index)
        )
        if resolved_pair_index < 0:
            raise ValueError("Mechanical layer pair index must be non-negative")

        updated = self.with_mechanical_layer(layer_1_id, enabled=True)
        updated = updated.with_mechanical_layer(layer_2_id, enabled=True)
        prefix = f"MECHPAIR{resolved_pair_index}"
        updated = updated._with_segment_value(
            f"{prefix}L1",
            f"MECHANICAL{_mechanical_layer_number(layer_1_id)}",
            preferred_segment_key="LAYERPAIR0LOW",
        )
        return updated._with_segment_value(
            f"{prefix}L2",
            f"MECHANICAL{_mechanical_layer_number(layer_2_id)}",
            preferred_segment_key=f"{prefix}L1",
        )

    def _segment_index_for_key(self, key: str) -> int | None:
        for index, segment in enumerate(self.segments):
            if segment.get_value(key) is not None:
                return index
        return None

    def _segment_index_for_entry_predicate(
        self,
        predicate: Callable[[PcbDocBoardDataEntry], bool],
    ) -> int | None:
        for index, segment in enumerate(self.segments):
            if any(predicate(entry) for entry in segment.entries):
                return index
        return None


class _PcbDocAsciiBoardDataStreamMixin:
    record: PcbDocBoardDataSegment
    trailing_nul: bool

    def build_stream(self) -> bytes:
        body = self.record.serialize()
        if self.trailing_nul:
            body += "\x00"
        return _build_length_prefixed_ascii(body)


@dataclass(frozen=True)
class PcbDocAsciiRecordData(_PcbDocAsciiBoardDataStreamMixin):
    """
    Owner for single-record length-prefixed ASCII streams.
    """

    record: PcbDocBoardDataSegment
    trailing_nul: bool = True

    @classmethod
    def from_bytes(cls, data: bytes) -> "PcbDocAsciiRecordData":
        if len(data) < 4:
            raise ValueError("Invalid ASCII record stream")
        length = struct.unpack("<I", data[:4])[0]
        if len(data) < 4 + length:
            raise ValueError("Invalid ASCII record stream")
        body_bytes = data[4 : 4 + length]
        trailing_nul = body_bytes.endswith(b"\x00")
        if trailing_nul:
            body_bytes = body_bytes[:-1]
        return cls(
            record=PcbDocBoardDataSegment.from_text(
                body_bytes.decode("cp1252", errors="replace")
            ),
            trailing_nul=trailing_nul,
        )

    def get_value(self, key: str, default: str | None = None) -> str | None:
        return self.record.get_value(key, default=default)

    def with_value(
        self, key: str, value: str, occurrence: int = 0
    ) -> "PcbDocAsciiRecordData":
        return PcbDocAsciiRecordData(
            record=self.record.with_updated_value(key, value, occurrence=occurrence),
            trailing_nul=self.trailing_nul,
        )


@dataclass(frozen=True)
class PcbDocPadViaLibraryData(_PcbDocAsciiBoardDataStreamMixin):
    """
    Typed owner for `PadViaLibrary/*` and `PadViaLibraryCache/*`.
    """

    record: PcbDocBoardDataSegment
    trailing_nul: bool = True

    @classmethod
    def from_bytes(cls, data: bytes) -> "PcbDocPadViaLibraryData":
        if len(data) < 4:
            raise ValueError("Invalid PadViaLibrary stream")
        length = struct.unpack("<I", data[:4])[0]
        if len(data) < 4 + length:
            raise ValueError("Invalid PadViaLibrary stream")
        body_bytes = data[4 : 4 + length]
        trailing_nul = body_bytes.endswith(b"\x00")
        if trailing_nul:
            body_bytes = body_bytes[:-1]
        return cls(
            record=PcbDocBoardDataSegment.from_text(
                body_bytes.decode("cp1252", errors="replace")
            ),
            trailing_nul=trailing_nul,
        )

    @classmethod
    def default(
        cls,
        *,
        library_id: uuid.UUID,
        library_name: str = "<Local>",
        display_units: int = 1,
    ) -> "PcbDocPadViaLibraryData":
        return cls(
            record=PcbDocBoardDataSegment(
                entries=(
                    PcbDocBoardDataEntry(
                        raw=f"PADVIALIBRARY.LIBRARYID={{{str(library_id).upper()}}}"
                    ),
                    PcbDocBoardDataEntry(
                        raw=f"PADVIALIBRARY.LIBRARYNAME={library_name}"
                    ),
                    PcbDocBoardDataEntry(
                        raw=f"PADVIALIBRARY.DISPLAYUNITS={display_units}"
                    ),
                ),
                leading_pipe=True,
            ),
            trailing_nul=True,
        )

    @property
    def library_id(self) -> uuid.UUID:
        value = self.record.get_value("PADVIALIBRARY.LIBRARYID")
        if value is None:
            raise KeyError("PADVIALIBRARY.LIBRARYID not found")
        return uuid.UUID(value.strip("{}"))

    @property
    def library_name(self) -> str | None:
        return self.record.get_value("PADVIALIBRARY.LIBRARYNAME")

    @property
    def display_units(self) -> int | None:
        value = self.record.get_value("PADVIALIBRARY.DISPLAYUNITS")
        return None if value is None else int(value)

    def with_library_id(self, value: uuid.UUID) -> "PcbDocPadViaLibraryData":
        return PcbDocPadViaLibraryData(
            record=self.record.with_updated_value(
                "PADVIALIBRARY.LIBRARYID",
                f"{{{str(value).upper()}}}",
            ),
            trailing_nul=self.trailing_nul,
        )

    def with_library_name(self, value: str) -> "PcbDocPadViaLibraryData":
        return PcbDocPadViaLibraryData(
            record=self.record.with_updated_value("PADVIALIBRARY.LIBRARYNAME", value),
            trailing_nul=self.trailing_nul,
        )

    def with_display_units(self, value: int) -> "PcbDocPadViaLibraryData":
        return PcbDocPadViaLibraryData(
            record=self.record.with_updated_value(
                "PADVIALIBRARY.DISPLAYUNITS", str(value)
            ),
            trailing_nul=self.trailing_nul,
        )


@dataclass(frozen=True)
class PcbDocConstraintManagerData:
    """
    Typed owner for the UTF-16LE `ConstraintManager/Data` token stream.
    """

    token: str

    @classmethod
    def from_bytes(cls, data: bytes) -> "PcbDocConstraintManagerData":
        return cls(token=_extract_length_prefixed_utf16le_body(data))

    @classmethod
    def default(cls) -> "PcbDocConstraintManagerData":
        return cls(token=_DEFAULT_CONSTRAINT_MANAGER_TOKEN)

    def build_stream(self) -> bytes:
        return _build_length_prefixed_utf16le(self.token + "\x00")

    def with_token(self, value: str) -> "PcbDocConstraintManagerData":
        return PcbDocConstraintManagerData(token=value)


@dataclass(frozen=True)
class PcbDocSignalClassesData(_PcbDocAsciiBoardDataStreamMixin):
    """
    Typed owner for the single-record `SignalClasses/Data` stream.
    """

    record: PcbDocBoardDataSegment
    trailing_nul: bool = True

    @classmethod
    def from_bytes(cls, data: bytes) -> "PcbDocSignalClassesData":
        if len(data) < 4:
            raise ValueError("Invalid SignalClasses stream")
        length = struct.unpack("<I", data[:4])[0]
        if len(data) < 4 + length:
            raise ValueError("Invalid SignalClasses stream")
        body_bytes = data[4 : 4 + length]
        trailing_nul = body_bytes.endswith(b"\x00")
        if trailing_nul:
            body_bytes = body_bytes[:-1]
        return cls(
            record=PcbDocBoardDataSegment.from_text(
                body_bytes.decode("cp1252", errors="replace")
            ),
            trailing_nul=trailing_nul,
        )

    @classmethod
    def default(cls) -> "PcbDocSignalClassesData":
        return cls(
            record=PcbDocBoardDataSegment(
                entries=(
                    PcbDocBoardDataEntry(raw="SELECTION=FALSE"),
                    PcbDocBoardDataEntry(raw="LAYER=MULTILAYER"),
                    PcbDocBoardDataEntry(raw="LOCKED=FALSE"),
                    PcbDocBoardDataEntry(raw="POLYGONOUTLINE=FALSE"),
                    PcbDocBoardDataEntry(raw="USERROUTED=TRUE"),
                    PcbDocBoardDataEntry(raw="KEEPOUT=FALSE"),
                    PcbDocBoardDataEntry(raw="UNIONINDEX=0"),
                    PcbDocBoardDataEntry(raw=f"NAME={_DEFAULT_SIGNAL_CLASS_NAME}"),
                    PcbDocBoardDataEntry(raw=f"KIND={_DEFAULT_SIGNAL_CLASS_KIND}"),
                    PcbDocBoardDataEntry(raw="SUPERCLASS=TRUE"),
                    PcbDocBoardDataEntry(raw="SELECTED=FALSE"),
                    PcbDocBoardDataEntry(raw="SCHAUTOGENERATEDCLUSTER=FALSE"),
                    PcbDocBoardDataEntry(
                        raw=f"UNIQUEID={_DEFAULT_SIGNAL_CLASS_UNIQUE_ID}"
                    ),
                ),
                leading_pipe=True,
            ),
            trailing_nul=True,
        )

    @property
    def unique_id(self) -> str | None:
        return self.record.get_value("UNIQUEID")

    @property
    def name(self) -> str | None:
        return self.record.get_value("NAME")

    @property
    def kind(self) -> int | None:
        value = self.record.get_value("KIND")
        return None if value is None else int(value)

