@dataclass(frozen=True)
class PcbDocLengthPrefixedBytesData:
    """
    Owner for opaque `[uint32 len][payload]` streams like `FileHeader`.
    """

    payload: bytes
    trailing_bytes: bytes = b""

    @classmethod
    def from_bytes(cls, data: bytes) -> "PcbDocLengthPrefixedBytesData":
        if len(data) < 4:
            raise ValueError("Invalid length-prefixed opaque stream")
        length = struct.unpack("<I", data[:4])[0]
        if len(data) < 4 + length:
            raise ValueError("Invalid length-prefixed opaque stream")
        return cls(
            payload=bytes(data[4 : 4 + length]),
            trailing_bytes=bytes(data[4 + length :]),
        )

    def build_stream(self) -> bytes:
        return struct.pack("<I", len(self.payload)) + self.payload + self.trailing_bytes


