    def set_outline_vertices_mils(
        self,
        vertices_mils: Sequence[tuple[float, float]],
    ) -> "PcbDocBuilder":
        """
        Replace the board outline with an explicit polygon in mils.
        """
        return self.set_board_outline(_outline_from_points(vertices_mils))

    def set_board_outline(self, outline: AltiumBoardOutline) -> "PcbDocBuilder":
        """
        Replace the board outline with explicit line/arc outline geometry.
        """
        self.board_data = self.board_data.with_outline(outline)
        self.board_regions_data = self.board_regions_data.with_outline_vertices(
            _outline_points_for_board_region(outline)
        )
        return self

    def set_outline_rectangle_mils(
        self,
        left: float,
        bottom: float,
        right: float,
        top: float,
    ) -> "PcbDocBuilder":
        """
        Set the board outline to an axis-aligned rectangle in mils.
        """
        return self.set_outline_vertices_mils(
            (
                (left, bottom),
                (right, bottom),
                (right, top),
                (left, top),
            )
        )

    def set_outline_circle_mils(
        self,
        *,
        center_mils: tuple[float, float],
        diameter_mils: float,
        vertex_count: int = 64,
    ) -> "PcbDocBuilder":
        """
        Approximate a circular board outline with evenly spaced vertices.

        Board6/Data stores outline geometry as a polygon, so authored circles
        are represented as a regular polygon approximation.
        """
        if diameter_mils <= 0:
            raise ValueError("Circle diameter must be positive")
        if vertex_count < 8:
            raise ValueError("Circle outline requires at least 8 vertices")

        center_x, center_y = center_mils
        radius_mils = diameter_mils / 2.0
        vertices: list[tuple[float, float]] = []
        for index in range(vertex_count):
            angle = 2.0 * math.pi * index / vertex_count
            x_mils = round(center_x + radius_mils * math.cos(angle), 6)
            y_mils = round(center_y + radius_mils * math.sin(angle), 6)
            vertices.append((x_mils, y_mils))
        return self.set_outline_vertices_mils(vertices)

    def set_origin_mils(self, x_mils: float, y_mils: float) -> "PcbDocBuilder":
        """
        Set the board origin in mils.
        """
        self.board_data = self.board_data.with_origin_mils(x_mils, y_mils)
        return self

    def set_origin_to_outline_lower_left(self) -> "PcbDocBuilder":
        """
        Derive the board origin from the outline's lower-left bounds.
        """
        outline = self.board_data.top_level_board.outline
        if outline is None or not outline.vertices:
            raise ValueError(
                "Board outline is required before deriving lower-left origin"
            )
        min_x = min(vertex.x_mils for vertex in outline.vertices)
        min_y = min(vertex.y_mils for vertex in outline.vertices)
        return self.set_origin_mils(min_x, min_y)

